import React from 'react';
import { useStatus } from '../contexts/StatusContext';
import { 
  MenuIcon, 
  CloseIcon,
  NetworkIcon,
  LoadingIcon,
  RefreshIcon,
  NotificationIcon,
  SettingsIcon
} from './Icons';

interface HeaderProps {
  sidebarOpen: boolean;
  setSidebarOpen: (open: boolean) => void;
  sidebarCollapsed: boolean;
  setSidebarCollapsed: (collapsed: boolean) => void;
}

export const Header: React.FC<HeaderProps> = ({ 
  sidebarOpen, 
  setSidebarOpen, 
  sidebarCollapsed, 
  setSidebarCollapsed 
}) => {
  const { state } = useStatus();

  const getStatusText = () => {
    switch (state.connectionStatus) {
      case 'connected':
        return 'Підключено';
      case 'connecting':
        return 'Підключення...';
      case 'disconnected':
        return 'Відключено';
      case 'error':
        return 'Помилка';
      default:
        return 'Невідомо';
    }
  };

  const getStatusColor = () => {
    switch (state.connectionStatus) {
      case 'connected':
        return 'text-success-600';
      case 'connecting':
        return 'text-warning-600';
      case 'disconnected':
      case 'error':
        return 'text-error-600';
      default:
        return 'text-secondary-600';
    }
  };

  return (
    <header className="bg-white shadow-sm border-b border-secondary-200 h-16 fixed top-0 left-0 right-0 z-50">
      <div className="flex items-center justify-between h-full px-4">
        {/* Left side */}
        <div className="flex items-center space-x-3">
          {/* Mobile menu button */}
          <button
            onClick={() => setSidebarOpen(!sidebarOpen)}
            className="lg:hidden p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-lg transition-all duration-200 w-10 h-10 flex items-center justify-center"
          >
            {sidebarOpen ? <CloseIcon size="lg" /> : <MenuIcon size="lg" />}
          </button>

          {/* Desktop sidebar toggle */}
          <button
            onClick={() => setSidebarCollapsed(!sidebarCollapsed)}
            className="hidden lg:flex p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-lg transition-all duration-200 w-10 h-10 items-center justify-center"
          >
            <MenuIcon size="lg" />
          </button>

          {/* Logo */}
          <div className="flex items-center space-x-3 ml-1">
            <div className="w-10 h-10 gradient-primary rounded-lg flex items-center justify-center text-white font-bold text-sm shadow-md">
              TC
            </div>
            <span className="hidden md:block text-lg font-semibold text-secondary-900">
              TetraCore Hub
            </span>
          </div>
        </div>

        {/* Right side */}
        <div className="flex items-center space-x-2">
          {/* Connection status */}
          <div className="hidden md:flex items-center space-x-2 px-3 py-2 bg-secondary-50 rounded-lg border border-secondary-200">
            {state.connectionStatus === "connecting" ? (
              <LoadingIcon size="sm" className="text-warning-500" />
            ) : (
              <NetworkIcon size="sm" className={getStatusColor()} />
            )}
            <span className={`text-sm font-medium ${getStatusColor()}`}>
              {getStatusText()}
            </span>
          </div>

          {/* Notifications */}
          <button className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-lg transition-all duration-200 relative w-10 h-10 flex items-center justify-center">
            <NotificationIcon size="lg" />
            {state.alerts.length > 0 && (
              <span className="absolute -top-1 -right-1 h-5 w-5 bg-error-500 text-white text-xs rounded-full flex items-center justify-center font-medium">
                {state.alerts.length > 9 ? '9+' : state.alerts.length}
              </span>
            )}
          </button>

          {/* Refresh button */}
          <button
            onClick={() => window.location.reload()}
            className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-lg transition-all duration-200 w-10 h-10 flex items-center justify-center"
          >
            <RefreshIcon size="lg" />
          </button>

          {/* Settings */}
          <button className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-lg transition-all duration-200 w-10 h-10 flex items-center justify-center">
            <SettingsIcon size="lg" />
          </button>
        </div>
      </div>
    </header>
  );
};
